'use strict';

function copyCard(card) {
  if (card === null || typeof card !== 'object' ||
      typeof card.name !== 'string' || typeof card.summary !== 'string' ||
      !(typeof card.image === 'string' || card.image === null)) {
    throw new TypeError('invalid card');
  }
  return { ...card };
}

function createShowcaseState(cards = []) {
  if (!Array.isArray(cards)) throw new TypeError('cards must be an array');
  return {
    drawerOpen: false,
    dialogOpen: false,
    scrollLocked: false,
    cards: cards.map(copyCard)
  };
}

function reduceShowcase(state, action) {
  if (state === null || typeof state !== 'object' || !Array.isArray(state.cards) ||
      action === null || typeof action !== 'object' || typeof action.type !== 'string') {
    throw new TypeError('invalid state or action');
  }

  switch (action.type) {
    case 'TOGGLE_DRAWER': {
      const drawerOpen = !state.drawerOpen;
      return { ...state, drawerOpen, dialogOpen: false, scrollLocked: drawerOpen };
    }
    case 'CLOSE_DRAWER':
      return { ...state, drawerOpen: false, scrollLocked: true };
    case 'OPEN_DIALOG':
      return { ...state, drawerOpen: false, dialogOpen: true, scrollLocked: true };
    case 'CLOSE_DIALOG':
      return { ...state, dialogOpen: false, scrollLocked: false };
    case 'BACKDROP':
      return { ...state, drawerOpen: false, dialogOpen: false, scrollLocked: false };
    case 'SUBMIT_CARD': {
      const card = copyCard(action.card);
      return {
        ...state,
        drawerOpen: false,
        dialogOpen: false,
        scrollLocked: false,
        cards: [...state.cards, card]
      };
    }
    default:
      throw new TypeError('unknown action');
  }
}

module.exports = { createShowcaseState, reduceShowcase };

