'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['createShowcaseState', 'reduceShowcase']);
const { createShowcaseState, reduceShowcase } = api;

assert.deepEqual(createShowcaseState(), { drawerOpen: false, dialogOpen: false, scrollLocked: false, cards: [] });
const card = { name: 'One', summary: 'First', image: null, extra: 9 };
const cards = [card];
const initial = createShowcaseState(cards);
assert.deepEqual(initial, { drawerOpen: false, dialogOpen: false, scrollLocked: false, cards: [{ name: 'One', summary: 'First', image: null, extra: 9 }] });
assert.notStrictEqual(initial.cards, cards);
assert.notStrictEqual(initial.cards[0], card);
card.name = 'mutated';
cards.push({ name: 'Two', summary: 'Second', image: 'x' });
assert.equal(initial.cards[0].name, 'One');
assert.equal(initial.cards.length, 1);

for (const bad of [null, {}, 'x', 2]) assert.throws(() => createShowcaseState(bad), TypeError);
for (const badCard of [null, {}, { name: 1, summary: 's', image: null }, { name: 'n', summary: null, image: null }, { name: 'n', summary: 's', image: 2 }]) {
  assert.throws(() => createShowcaseState([badCard]), TypeError);
}

let state = reduceShowcase(initial, { type: 'TOGGLE_DRAWER' });
assert.deepEqual({ drawerOpen: state.drawerOpen, dialogOpen: state.dialogOpen, scrollLocked: state.scrollLocked }, { drawerOpen: true, dialogOpen: false, scrollLocked: true });
assert.notStrictEqual(state, initial);
assert.strictEqual(state.cards, initial.cards);
let next = reduceShowcase(state, { type: 'TOGGLE_DRAWER' });
assert.deepEqual({ drawerOpen: next.drawerOpen, dialogOpen: next.dialogOpen, scrollLocked: next.scrollLocked }, { drawerOpen: false, dialogOpen: false, scrollLocked: false });
assert.strictEqual(next.cards, state.cards);

state = reduceShowcase(initial, { type: 'OPEN_DIALOG' });
assert.deepEqual({ drawerOpen: state.drawerOpen, dialogOpen: state.dialogOpen, scrollLocked: state.scrollLocked }, { drawerOpen: false, dialogOpen: true, scrollLocked: true });
next = reduceShowcase(state, { type: 'CLOSE_DIALOG' });
assert.deepEqual({ drawerOpen: next.drawerOpen, dialogOpen: next.dialogOpen, scrollLocked: next.scrollLocked }, { drawerOpen: false, dialogOpen: false, scrollLocked: false });
assert.strictEqual(next.cards, state.cards);

const drawerState = reduceShowcase(initial, { type: 'TOGGLE_DRAWER' });
const dialogFromDrawer = reduceShowcase(drawerState, { type: 'OPEN_DIALOG' });
assert.equal(dialogFromDrawer.drawerOpen, false);
assert.equal(dialogFromDrawer.dialogOpen, true);
const closedDrawer = reduceShowcase(drawerState, { type: 'CLOSE_DRAWER' });
assert.equal(closedDrawer.drawerOpen, false);
assert.equal(closedDrawer.scrollLocked, false);
const backdrop = reduceShowcase(state, { type: 'BACKDROP' });
assert.deepEqual({ drawerOpen: backdrop.drawerOpen, dialogOpen: backdrop.dialogOpen, scrollLocked: backdrop.scrollLocked }, { drawerOpen: false, dialogOpen: false, scrollLocked: false });
assert.strictEqual(backdrop.cards, state.cards);

const submittedSource = { name: 'New', summary: 'Summary', image: 'pic.png', extra: 'kept' };
const submitted = reduceShowcase(state, { type: 'SUBMIT_CARD', card: submittedSource });
assert.notStrictEqual(submitted.cards, state.cards);
assert.strictEqual(submitted.cards[0], state.cards[0]);
assert.notStrictEqual(submitted.cards[1], submittedSource);
assert.deepEqual(submitted.cards[1], submittedSource);
assert.equal(submitted.drawerOpen, false);
assert.equal(submitted.dialogOpen, false);
assert.equal(submitted.scrollLocked, false);
submittedSource.name = 'later';
assert.equal(submitted.cards[1].name, 'New');
assert.equal(state.cards.length, 1);

for (const action of [null, {}, { type: 'UNKNOWN' }, { type: 'SUBMIT_CARD' }, { type: 'SUBMIT_CARD', card: { name: 'x', summary: 'y', image: false } }]) {
  assert.throws(() => reduceShowcase(initial, action), TypeError);
}

